package middleware
import("bytes";"net/http";"time";redisv9 "github.com/redis/go-redis/v9";"go-repair-center/internal/transport/http/response")
type captureWriter struct{header http.Header;status int;body bytes.Buffer}
func newCapture()*captureWriter{return &captureWriter{header:make(http.Header),status:200}}
func(w *captureWriter)Header()http.Header{return w.header};func(w *captureWriter)WriteHeader(status int){w.status=status};func(w *captureWriter)Write(p []byte)(int,error){return w.body.Write(p)}
func Idempotency(client *redisv9.Client,ttl time.Duration)func(http.Handler)http.Handler{return func(next http.Handler)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){key:=r.Header.Get("Idempotency-Key");if key==""{response.Error(w,400,response.CodeInvalidParameter,"Idempotency-Key required",RequestID(r.Context()));return};redisKey:="idem:"+UserIDString(r.Context())+":"+r.Method+":"+r.URL.Path+":"+key;if cached,err:=client.Get(r.Context(),redisKey).Bytes();err==nil{w.Header().Set("Content-Type","application/json");w.Write(cached);return};locked,err:=client.SetNX(r.Context(),redisKey+":lock","1",30*time.Second).Result();if err==nil&&!locked{response.Error(w,409,response.CodeIdempotencyConflict,"request already in progress",RequestID(r.Context()));return};defer client.Del(r.Context(),redisKey+":lock");capture:=newCapture();next.ServeHTTP(capture,r);for name,values:=range capture.header{for _,value:=range values{w.Header().Add(name,value)}};w.WriteHeader(capture.status);body:=capture.body.Bytes();w.Write(body);if capture.status>=200&&capture.status<300{_ = client.Set(r.Context(),redisKey,body,ttl).Err()}})}}